//! `mediaanon-gui` — desktop front-end of MediaAnonymizer.
//!
//! Usage: `mediaanon-gui [FILES OR FOLDERS...]` (they pre-fill the queue).
//! Set `MEDIAANON_GUI_SCREENSHOT=out.png` to save a screenshot once the
//! window is populated and exit (used to produce the documentation images).

#![cfg_attr(all(windows, not(debug_assertions)), windows_subsystem = "windows")]

mod app;
mod preview;
mod queue;
mod settings;
mod timeline;
mod worker;

use std::path::PathBuf;

/// Window / taskbar icon (generated by `packaging/make_icons.py`).
static ICON: &[u8] = include_bytes!("../../../packaging/icons/icon.png");

fn main() -> eframe::Result {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_env("MEDIAANON_LOG")
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("warn,ort=warn")),
        )
        .init();

    let files: Vec<PathBuf> = std::env::args_os().skip(1).map(PathBuf::from).collect();
    let screenshot = std::env::var_os("MEDIAANON_GUI_SCREENSHOT").filter(|p| !p.is_empty()).map(PathBuf::from);

    let mut viewport = eframe::egui::ViewportBuilder::default();
    if let Ok(icon) = eframe::icon_data::from_png_bytes(ICON) {
        viewport = viewport.with_icon(icon);
    }
    let options = eframe::NativeOptions {
        viewport: viewport
            .with_title("MediaAnonymizer")
            .with_inner_size([1360.0, 820.0])
            .with_min_inner_size([900.0, 560.0])
            .with_drag_and_drop(true),
        // A screenshot run must not pick up (or overwrite) the user's settings.
        persist_window: screenshot.is_none(),
        persistence_path: screenshot.as_ref().map(|_| std::env::temp_dir().join("mediaanon-gui-screenshot.ron")),
        ..Default::default()
    };
    eframe::run_native(
        "MediaAnonymizer",
        options,
        Box::new(move |cc| Ok(Box::new(app::App::new(cc, files, screenshot)))),
    )
}
